import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# -------------------- CUDA / C++ extension --------------------
src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

using half = __half;

__global__ void conv3d_kernel(const half* __restrict__ input,
                              const half* __restrict__ weight,
                              half* __restrict__ output,
                              int N, int C_in, int C_out,
                              int D, int H, int W,
                              int K,
                              int D_out, int H_out, int W_out) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C_out * D_out * H_out * W_out;
    if (idx >= total) return;

    int w_out = idx % W_out;
    int tmp  = idx / W_out;
    int h_out = tmp % H_out;
    tmp = tmp / H_out;
    int d_out = tmp % D_out;
    tmp = tmp / D_out;
    int c_out = tmp % C_out;
    int n = tmp / C_out;

    float sum = 0.0f;
    for (int c_in = 0; c_in < C_in; ++c_in) {
        for (int kd = 0; kd < K; ++kd) {
            int d_in = d_out + kd;
            for (int kh = 0; kh < K; ++kh) {
                int h_in = h_out + kh;
                for (int kw = 0; kw < K; ++kw) {
                    int w_in = w_out + kw;
                    int input_idx = (((((n * C_in) + c_in) * D) + d_in) * H + h_in) * W + w_in;
                    int weight_idx = (((((c_out * C_in) + c_in) * K) + kd) * K + kh) * K + kw;
                    sum += __half2float(input[input_idx]) * __half2float(weight[weight_idx]);
                }
            }
        }
    }

    int out_idx = (((((n * C_out) + c_out) * D_out) + d_out) * H_out + h_out) * W_out + w_out;
    output[out_idx] = __float2half(sum);
}

torch::Tensor conv3d_forward(torch::Tensor input, torch::Tensor weight) {
    TORCH_CHECK(input.is_cuda(), "input must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(input.dtype() == torch::kHalf, "input must be half");
    TORCH_CHECK(weight.dtype() == torch::kHalf, "weight must be half");

    const int64_t N = input.size(0);
    const int64_t C_in = input.size(1);
    const int64_t D = input.size(2);
    const int64_t H = input.size(3);
    const int64_t W = input.size(4);
    const int K = weight.size(2);          // kernel dimension (assumed cubic)
    const int64_t C_out = weight.size(0);

    const int64_t D_out = D - K + 1;
    const int64_t H_out = H - K + 1;
    const int64_t W_out = W - K + 1;

    auto output = torch::zeros({N, C_out, D_out, H_out, W_out}, input.options());

    const int threads = 256;
    const int64_t total = N * C_out * D_out * H_out * W_out;
    const int blocks = (total + threads - 1) / threads;

    conv3d_kernel<<<blocks, threads>>>(
        reinterpret_cast<half*>(input.data_ptr()),
        reinterpret_cast<half*>(weight.data_ptr()),
        reinterpret_cast<half*>(output.data_ptr()),
        static_cast<int>(N),
        static_cast<int>(C_in),
        static_cast<int>(C_out),
        static_cast<int>(D),
        static_cast<int>(H),
        static_cast<int>(W),
        K,
        static_cast<int>(D_out),
        static_cast<int>(H_out),
        static_cast<int>(W_out));

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA kernel launch error: %s\\n", cudaGetErrorString(err));
    }
    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv3d_forward", &conv3d_forward, "3D convolution forward (CUDA)");
}
'''

conv3d_ext = load_inline(name='conv3d_ext',
                         cpp_sources=src,
                         functions=['conv3d_forward'],
                         verbose=False)

# -------------------- Python model wrapper --------------------
class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model using a custom CUDA kernel.
    Only stride=1, padding=0, dilation=1, groups=1, bias=False are supported,
    matching the default arguments used by the reference implementation.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int):
        super().__init__()
        self.kernel_size = kernel_size
        # weight shape: (out_channels, in_channels, K, K, K)
        self.weight = nn.Parameter(
            torch.empty(out_channels,
                        in_channels,
                        kernel_size,
                        kernel_size,
                        kernel_size,
                        dtype=torch.half,
                        device='cuda')
        )
        # Kaiming uniform initialization (same as nn.Conv3d default)
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure input is half‑precision and on CUDA
        if x.dtype != torch.half:
            x = x.half()
        if not x.is_cuda:
            x = x.cuda()
        return conv3d_ext.conv3d_forward(x, self.weight)
